Inductive wf_ctx : ctx -> Prop :=
    wf_ctx_empty : {{ ⊢ ⋅ }}
  | wf_ctx_extend : forall (Γ : ctx) (i : nat) (A : typ),
                    {{ ⊢ Γ }} -> {{ Γ ⊢ A : Type@i }} -> {{ ⊢ Γ, A }}
  with wf_ctx_sub : ctx -> ctx -> Prop :=
    wf_ctx_sub_empty : {{ ⊢ ⋅ ⊆ ⋅ }}
  | wf_ctx_sub_extend : forall (Γ Δ : ctx) (i : nat) (A A' : typ),
                        {{ ⊢ Γ ⊆ Δ }} ->
                        {{ Γ ⊢ A : Type@i }} ->
                        {{ Δ ⊢ A' : Type@i }} ->
                        {{ Γ ⊢ A ⊆ A' }} -> {{ ⊢ Γ, A ⊆ Δ, A' }}
  with wf_exp : ctx -> typ -> typ -> Prop :=
    wf_typ : forall (Γ : ctx) (i : nat),
             {{ ⊢ Γ }} -> {{ Γ ⊢ Type@i : Type@(S i) }}
  | wf_nat : forall Γ : ctx, {{ ⊢ Γ }} -> {{ Γ ⊢ ℕ : Type@0 }}
  | wf_zero : forall Γ : ctx, {{ ⊢ Γ }} -> {{ Γ ⊢ zero : ℕ }}
  | wf_succ : forall (Γ : ctx) (M : typ),
