python3 - <<'PY'
import re
lines=open('/workspace/Checks.out').read().splitlines()
entries=[]; cur=None
for ln in lines:
    if re.match(r'^[A-Za-z_][A-Za-z0-9_]*$', ln.strip()) and not ln.startswith(' '):
        if cur: entries.append(cur)
        cur=[ln.strip(),'']
    elif cur is not None:
        cur[1]+=' '+ln.strip()
if cur: entries.append(cur)
def parse_sig(t):
    t=t.strip()
    if t.startswith(': '): t=t[2:]
    nb=0
    while True:
        t=t.strip()
        if not t.startswith('forall'): break
        t=t[len('forall'):].strip()
        while t.startswith('('):
            depth=0; i=0
            while i<len(t):
                if t[i]=='(': depth+=1
                elif t[i]==')':
                    depth-=1
                    if depth==0: break
                i+=1
            group=t[1:i]
            nb+=len(group.split(':')[0].split())
            t=t[i+1:].strip()
        if t.startswith(','): t=t[1:].strip()
    prem=t.count('}} ->')
    return nb,prem,t
for name,text in entries:
    nb,prem,t=parse_sig(text)
    print(f'Arguments {name} '+'{'+' '.join(['_']*nb)+'}'+(' '+' '.join(['_']*prem) if prem else '')+'.')
PY

